local c=require("filesystem")
local a={}
local g="/etc/udev/rules.d/"
local h="autogenerated.lua"
local function e(b,d)
return"/"..table.concat(c.segments(b.."/"..d),"/")
end
function a.loadRules(b)
checkArg(1,b,"string","nil")
b=b or g
a.rules={}
a.rules[e(b,h)]={}
for d in c.list(b)do
if d:match("%.lua$")then
local c=e(b,d)
local b=io.open(c)
if b then
local d=load("return {"..b:read("*a").."}")
b:close()
if d then
local b,f=pcall(d)
if b and type(f)=="table"then
local b={}
a.rules[c]=b
for c,c in ipairs(f)do
if type(c)=="table"then
b[#b+1]=c
end
end
end
end
end
end
end
end
function a.saveRule(c,d)
checkArg(1,c,"table")
checkArg(2,d,"string")
local b=io.open(d,"w")
if not b then return end
for d,d in ipairs(c)do
b:write(require("serialization").serialize(d),",\n")
end
b:close()
end
function a.saveRules(b)
for c,d in pairs(b)do
a.saveRule(d,c)
end
end
local function i(b)
checkArg(1,b,"table")
for f,c in pairs(a.rules)do
for j,d in ipairs(c)do
if d.address==b.address then
return d,j,c,f
end
end
end
end
function a.getDeviceLabel(b)
local c=i(b)
if c and c.label then
return c.label
elseif b.getLabel then
return b.getLabel()
end
end
function a.setDeviceLabel(b,j)
local c,d,d,f=i(b)
if not c then
if b.setLabel then
return b.setLabel(j)
end
f=e(g,h)
d=a.rules[f]
c={address=b.address}
d[#d+1]=c
end
c.label=j
a.saveRule(d,f)
end
return a
